import java.util.*;

class NumberUtility {

    static boolean isPrime(int n) {

        if (n < 2)
            return false;

        for (int i = 2; i * i <= n; i++) {

            if (n % i == 0)
                return false;
        }

        return true;
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        while (n-- > 0) {

            int value = sc.nextInt();

            System.out.println(
                    NumberUtility.isPrime(value)
                    ? "Prime"
                    : "Not Prime");
        }
    }
}

