import java.util.*;

class MatrixAnalyzer {

    private int[][] matrix;

    MatrixAnalyzer(int[][] matrix) {

        this.matrix = matrix;
    }

    public int maximum() {

        int max = Integer.MIN_VALUE;

        for (int[] row : matrix) {

            for (int value : row) {

                if (value > max)
                    max = value;
            }
        }

        return max;
    }

    public int minimum() {

        int min = Integer.MAX_VALUE;

        for (int[] row : matrix) {

            for (int value : row) {

                if (value < min)
                    min = value;
            }
        }

        return min;
    }

    public int maximumRow() {

        long maxSum =
                Long.MIN_VALUE;

        int result = 0;

        for (int i = 0;
             i < matrix.length;
             i++) {

            long sum = 0;

            for (int value : matrix[i])
                sum += value;

            if (sum > maxSum) {

                maxSum = sum;
                result = i + 1;
            }
        }

        return result;
    }

    public int maximumColumn() {

        int rows = matrix.length;
        int cols = matrix[0].length;

        long maxSum =
                Long.MIN_VALUE;

        int result = 0;

        for (int j = 0; j < cols; j++) {

            long sum = 0;

            for (int i = 0; i < rows; i++)
                sum += matrix[i][j];

            if (sum > maxSum) {

                maxSum = sum;
                result = j + 1;
            }
        }

        return result;
    }

    public long diagonalSum() {

        long sum = 0;

        int limit = Math.min(
                matrix.length,
                matrix[0].length);

        for (int i = 0; i < limit; i++)
            sum += matrix[i][i];

        return sum;
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        int[][] matrix =
                new int[rows][cols];

        for (int i = 0; i < rows; i++) {

            for (int j = 0; j < cols; j++) {

                matrix[i][j] = sc.nextInt();
            }
        }

        MatrixAnalyzer analyzer =
                new MatrixAnalyzer(matrix);

        System.out.println(
                "Maximum: "
                + analyzer.maximum());

        System.out.println(
                "Minimum: "
                + analyzer.minimum());

        System.out.println(
                "Maximum Row: "
                + analyzer.maximumRow());

        System.out.println(
                "Maximum Column: "
                + analyzer.maximumColumn());

        System.out.println(
                "Diagonal Sum: "
                + analyzer.diagonalSum());
    }
}
